/**
 * with-app-clip — Expo config plugin for BeaTrackFam Rewards.
 *
 * Adds a native App Clip target (`BeaTrackFamRewardsClip`, bundle ID
 * `com.beatrackfaminc.rewards.BeaTrackFamRewards`) to the iOS project generated by
 * `expo prebuild`, so the target survives every prebuild instead of being
 * wiped like a hand-added Xcode target would be.
 *
 * WHAT THE CLIP IS
 *   A tiny, pure-SwiftUI app (clip/ClipApp.swift — no React Native, no JS
 *   bundle) that mirrors the Rewards home screen: the loyalty pitch, the
 *   tier ladder (Fam → Loyal → Ride or Die) and how to earn, with buttons
 *   that hand off to the full app (beatrackfamrewards://) or the shop.
 *   The full React Native app can never fit an App Clip's 15 MB limit;
 *   the clip's sources + icons are ~40 KB and the built .app is SwiftUI
 *   + system frameworks only, so it stays far under the limit.
 *   The clip never signs anyone in and makes no network calls.
 *   Its entitlements (clip/BeaTrackFamRewardsClip.entitlements) carry
 *   parent-application-identifiers + on-demand-install-capable +
 *   associated-domains applinks:beatrackfam.info (so the clip can be
 *   invoked from https://beatrackfam.info links).
 *
 * HOW IT IS WIRED
 *   - clip/ sources are copied into ios/BeaTrackFamRewardsClip/ at prebuild
 *     time (withDangerousMod) and referenced from there.
 *   - A PBXNativeTarget with product type
 *     com.apple.product-type.application.on-demand-install-capable is added
 *     via withXcodeProject. (node-xcode's addTarget() has no App Clip type,
 *     so the target is built from its low-level APIs.)
 *   - The main app target depends on the clip target and gains an
 *     "Embed App Clips" copy phase (dstSubfolderSpec 16, CodeSignOnCopy),
 *     so the existing `xcodebuild archive -scheme BeaTrackFamRewards`
 *     builds the clip and embeds it in the archive automatically.
 *   - Signing: xcodebuild command-line build settings apply to EVERY
 *     target, so a single PROVISIONING_PROFILE_SPECIFIER on the archive
 *     command would force the main app's profile onto the clip and fail.
 *     The plugin therefore sets the profile per target, Release only
 *     (Debug keeps automatic signing so local dev builds still work):
 *       main app → "BeaTrackFam Rewards App Store" (existing profile)
 *       clip     → "BeaTrackFam Rewards App Clip" (Joey must create
 *                   this profile in the Apple Developer portal first)
 *     The workflow's archive step must NOT pass PROVISIONING_PROFILE_SPECIFIER
 *     on the command line anymore — see .github/workflows/ios-build.yml.
 *
 * PORTAL STEPS STILL NEEDED (Joey, before the first clip build works):
 *   1. Developer portal → Identifiers → App IDs: the App Clip App ID
 *      ALREADY EXISTS — "BeaTrackFam Rewards App Clip",
 *      com.beatrackfaminc.rewards.BeaTrackFamRewards (verified from
 *      Joey's portal screenshot Nov 10). Do NOT create another one.
 *   2. Developer portal → Profiles: NO App Clip provisioning profile
 *      exists yet (confirmed from Joey's screenshots Nov 10). Joey will
 *      create one — App Store distribution, for the App ID above,
 *      including the current Apple Distribution certificate (the Nov 6
 *      one) — named exactly "BeaTrackFam Rewards App Clip". That name
 *      is what this plugin (CLIP_PROFILE) and the workflow's
 *      ExportOptions mapping expect; it happens to match the App ID's
 *      name, which is fine — they are separate portal objects. The
 *      workflow uses -allowProvisioningUpdates, so once the profile
 *      exists the build fetches it automatically.
 *   3. App Store Connect → the Rewards app record → App Clip: create the
 *      App Clip experience (invocation URL / App Clip Code) when ready to
 *      let people launch the clip from a link, QR code or NFC tag. Without
 *      it the clip still ships inside the app; it just has no link entry.
 */
const { withDangerousMod, withXcodeProject } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const CLIP_TARGET_NAME = 'BeaTrackFamRewardsClip';
const CLIP_BUNDLE_ID = 'com.beatrackfaminc.rewards.BeaTrackFamRewards';
const CLIP_PROFILE = 'BeaTrackFam Rewards App Clip';
const MAIN_PROFILE = 'BeaTrackFam Rewards App Store';
const MAIN_TARGET_NAME = 'BeaTrackFamRewards';
const CLIP_DIR_NAME = 'BeaTrackFamRewardsClip';
const CLIP_PRODUCT_TYPE = 'com.apple.product-type.application.on-demand-install-capable';

// Quoting matches what Expo writes into project.pbxproj: bundle IDs,
// product names and device families are quoted; paths, versions and
// YES/NO flags are bare.
const q = (s) => `"${s}"`;

function targetUuidByName(project, name) {
  const section = project.pbxNativeTargetSection();
  for (const key of Object.keys(section)) {
    if (key.endsWith('_comment')) continue;
    const target = section[key];
    if (target && String(target.name).replace(/"/g, '') === name) return key;
  }
  return null;
}

function clipBuildSettings(config, isDebug) {
  const version = String(config.version || '1.0.0');
  const buildNumber = String((config.ios && config.ios.buildNumber) || '1000');
  const deploymentTarget = String((config.ios && config.ios.deploymentTarget) || '16.4');
  const settings = {
    ASSETCATALOG_COMPILER_APPICON_NAME: 'AppIcon',
    CLANG_ENABLE_MODULES: 'YES',
    CODE_SIGN_ENTITLEMENTS: `${CLIP_DIR_NAME}/${CLIP_TARGET_NAME}.entitlements`,
    CURRENT_PROJECT_VERSION: buildNumber,
    INFOPLIST_FILE: `${CLIP_DIR_NAME}/Info.plist`,
    IPHONEOS_DEPLOYMENT_TARGET: deploymentTarget,
    LD_RUNPATH_SEARCH_PATHS: ['"$(inherited)"', '"@executable_path/Frameworks"'],
    MARKETING_VERSION: version,
    PRODUCT_BUNDLE_IDENTIFIER: q(CLIP_BUNDLE_ID),
    PRODUCT_NAME: q(CLIP_TARGET_NAME),
    SKIP_INSTALL: 'YES',
    SWIFT_EMBED_LIBRARIES_WITH_INSTALL: 'YES',
    SWIFT_VERSION: '5.0',
    // Xcode requires the clip's UIDeviceFamily to EQUAL the parent app's
    // (Universal 1,2 here) — iPhone-only '1' fails ValidateEmbeddedBinary
    // at archive (run 50, Nov 10 2026). ASC's iPad rules for a universal
    // clip are met by the clip's full icon set (incl. 152 iPad) +
    // UISupportedInterfaceOrientations~ipad + UILaunchScreen in Info.plist.
    TARGETED_DEVICE_FAMILY: q('1,2'),
  };
  if (isDebug) {
    settings.GCC_PREPROCESSOR_DEFINITIONS = ['"DEBUG=1"', '"$(inherited)"'];
  } else {
    // Release only: Debug keeps automatic signing for local dev builds.
    settings.CODE_SIGN_STYLE = 'Manual';
    settings.PROVISIONING_PROFILE_SPECIFIER = q(CLIP_PROFILE);
  }
  return settings;
}

function withAppClip(config) {
  // 1. Copy the checked-in clip sources into the generated ios/ tree.
  config = withDangerousMod(config, [
    'ios',
    async (config) => {
      const src = path.join(config.modRequest.projectRoot, 'clip');
      const dest = path.join(config.modRequest.platformProjectRoot, CLIP_DIR_NAME);
      if (!fs.existsSync(src)) {
        throw new Error('[with-app-clip] clip/ source folder is missing from the repo.');
      }
      fs.rmSync(dest, { recursive: true, force: true });
      fs.cpSync(src, dest, { recursive: true });
      return config;
    },
  ]);

  // 2. Add the App Clip target to the generated Xcode project.
  config = withXcodeProject(config, (config) => {
    const project = config.modResults;
    const objects = project.hash.project.objects;

    // Idempotent: prebuild starts from a fresh project, but never add twice.
    if (project.pbxTargetByName(CLIP_TARGET_NAME)) return config;

    const mainTargetUuid = targetUuidByName(project, MAIN_TARGET_NAME);
    if (!mainTargetUuid) {
      throw new Error(`[with-app-clip] Main target "${MAIN_TARGET_NAME}" not found.`);
    }
    const mainTarget = project.pbxNativeTargetSection()[mainTargetUuid];

    // --- Build configurations (Debug + Release) for the clip target ---
    const configurations = project.addXCConfigurationList(
      [
        {
          name: 'Debug',
          isa: 'XCBuildConfiguration',
          buildSettings: clipBuildSettings(config, true),
        },
        {
          name: 'Release',
          isa: 'XCBuildConfiguration',
          buildSettings: clipBuildSettings(config, false),
        },
      ],
      'Release',
      `Build configuration list for PBXNativeTarget "${CLIP_TARGET_NAME}"`,
    );

    // --- Product file (BeaTrackFamRewardsClip.app) ---
    // embed+sign gives the PBXBuildFile entry CodeSignOnCopy, which the
    // Embed App Clips phase needs; group names the phase in the comment.
    const clipUuid = project.generateUuid();
    const productFile = project.addProductFile(CLIP_TARGET_NAME, {
      group: 'Embed App Clips',
      target: clipUuid,
      explicitFileType: '"wrapper.application"',
      embed: true,
      sign: true,
    });
    project.addToPbxBuildFileSection(productFile);

    // --- The native target itself (node-xcode has no App Clip type) ---
    const target = {
      uuid: clipUuid,
      pbxNativeTarget: {
        isa: 'PBXNativeTarget',
        buildConfigurationList: configurations.uuid,
        buildPhases: [],
        buildRules: [],
        dependencies: [],
        name: CLIP_TARGET_NAME,
        productName: CLIP_TARGET_NAME,
        productReference: productFile.fileRef,
        productType: q(CLIP_PRODUCT_TYPE),
      },
    };
    project.addToPbxNativeTargetSection(target);
    // addToPbxNativeTargetSection stores the (quoted) name as the comment;
    // keep the comment clean like the rest of the project.
    project.pbxNativeTargetSection()[`${clipUuid}_comment`] = CLIP_TARGET_NAME;
    project.addToPbxProjectSection(target);

    // Main app depends on the clip so the clip builds first, every time.
    // NOTE: addTargetDependency() silently no-ops when the
    // PBXTargetDependency / PBXContainerItemProxy sections don't exist yet
    // (this project has no dependencies), so create them first.
    if (!objects.PBXTargetDependency) objects.PBXTargetDependency = {};
    if (!objects.PBXContainerItemProxy) objects.PBXContainerItemProxy = {};
    project.addTargetDependency(mainTargetUuid, [clipUuid]);

    // --- Build phases for the clip target ---
    project.addBuildPhase([], 'PBXSourcesBuildPhase', 'Sources', clipUuid);
    project.addBuildPhase([], 'PBXFrameworksBuildPhase', 'Frameworks', clipUuid);
    project.addBuildPhase([], 'PBXResourcesBuildPhase', 'Resources', clipUuid);

    // --- Project navigator group (same convention as the main app group:
    //     group has no path; file refs carry the full relative path) ---
    const groupUuid = project.generateUuid();
    objects.PBXGroup[groupUuid] = {
      isa: 'PBXGroup',
      children: [],
      name: CLIP_DIR_NAME,
      sourceTree: '"<group>"',
    };
    objects.PBXGroup[`${groupUuid}_comment`] = CLIP_DIR_NAME;
    const mainGroupUuid = project.getFirstProject().firstProject.mainGroup;
    objects.PBXGroup[mainGroupUuid].children.push({
      value: groupUuid,
      comment: CLIP_DIR_NAME,
    });

    // --- Clip files: sources, resources, and ref-only files ---
    const swiftFile = project.addSourceFile(
      `${CLIP_DIR_NAME}/ClipApp.swift`,
      { target: clipUuid },
      groupUuid,
    );
    // NOTE: do NOT use addResourceFile() here — it calls
    // correctForResourcesPath(), which crashes (pbxGroupByName('Resources')
    // is null) because this project has no top-level "Resources" group.
    // addFile() + manual build-file wiring does the same job.
    const xcassets = project.addFile(`${CLIP_DIR_NAME}/Assets.xcassets`, groupUuid, {});
    xcassets.target = clipUuid;
    xcassets.uuid = project.generateUuid();
    project.addToPbxBuildFileSection(xcassets);
    project.addToPbxResourcesBuildPhase(xcassets);
    const infoPlist = project.addFile(`${CLIP_DIR_NAME}/Info.plist`, groupUuid, {});
    const entitlements = project.addFile(
      `${CLIP_DIR_NAME}/${CLIP_TARGET_NAME}.entitlements`,
      groupUuid,
      { lastKnownFileType: 'text.plist.xml' },
    );

    // node-xcode's pbxFileReferenceObj writes every key, including ones
    // whose value is undefined — the project would literally contain
    // `fileEncoding = undefined;`. Strip those keys so the generated
    // project matches what Xcode itself writes.
    for (const ref of [productFile, swiftFile, xcassets, infoPlist, entitlements]) {
      const obj = project.pbxFileReferenceSection()[ref.fileRef];
      for (const key of Object.keys(obj)) {
        if (obj[key] === undefined) delete obj[key];
      }
    }

    // --- "Embed App Clips" phase on the main app target ---
    // Built with the xcode API, not a hand-rolled phase object: the
    // hand-rolled form generated a phase that Xcode never executed in the
    // 2.0.0 archives (Nov 10, 2026 — clip built, never embedded, ASC said
    // HAS APP CLIP: NO twice). The API form with an explicit
    // $(CONTENTS_FOLDER_PATH)/AppClips destination mirrors the Motivation
    // plugin. The file entry is pushed only if not already present.
    project.addBuildPhase(
      [],
      'PBXCopyFilesBuildPhase',
      'Embed App Clips',
      mainTargetUuid,
      'dynamic_library',
      '"$(CONTENTS_FOLDER_PATH)/AppClips"'
    );
    const embedPhase = Object.values(
      objects.PBXCopyFilesBuildPhase || {}
    ).find(
      (ph) =>
        ph &&
        typeof ph.name === 'string' &&
        ph.name.includes('Embed App Clips')
    );
    if (
      embedPhase &&
      !embedPhase.files.some((f) => f.value === productFile.uuid)
    ) {
      embedPhase.files.push({
        value: productFile.uuid,
        comment: `${CLIP_TARGET_NAME}.app in Embed App Clips`,
      });
    }

    // --- Per-target signing (Release only) ---
    // The archive step must NOT pass PROVISIONING_PROFILE_SPECIFIER on the
    // command line: it would apply to every target and force the main
    // app's profile onto the clip. Each target carries its own profile.
    project.updateBuildProperty(
      'PROVISIONING_PROFILE_SPECIFIER',
      q(MAIN_PROFILE),
      'Release',
      MAIN_TARGET_NAME,
    );

    return config;
  });

  return config;
}

module.exports = withAppClip;
